# enumerate dihedral transforms each piece coordinates around local bounding incl marker; compare pair fitting >=1 shared marker
import itertools

def trans_cells(cells, k, refl=False):
    pts=[]
    for r,c,v in cells:
        if refl: c=-c
        for _ in range(k): r,c=c,-r
        pts.append((r,c,v))
    minr=min(x[0] for x in pts); minc=min(x[1] for x in pts)
    return [(r-minr,c-minc,v) for r,c,v in pts]
